css:
* { margin: 0px; padding: 0px; box-sizing: border-box; }
.snap-body { width: 320px; font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Inter, Roboto, sans-serif; background: rgb(13, 13, 15); color: rgb(250, 250, 250); font-size: 13px; line-height: 1.45; -webkit-font-smoothing: antialiased; }
.head { display: flex; align-items: center; gap: 11px; padding: 15px 16px 13px; }
.head .t { min-width: 0px; }
.head .t strong { display: block; font-size: 14px; font-weight: 600; letter-spacing: -0.01em; }
.head .t small { display: block; font-size: 12px; color: rgb(139, 139, 147); margin-top: 1px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.mark { width: 32px; height: 32px; flex: 0 0 auto; border-radius: 50%; display: grid; place-items: center; }
.mark.warn { background: rgba(239, 68, 68, 0.15); color: rgb(252, 165, 165); font-weight: 700; font-size: 16px; }
.mark.ok { background: rgba(22, 163, 74, 0.15); }
.mark.ok::after { content: ""; width: 9px; height: 9px; border-radius: 50%; background: rgb(74, 222, 128); }
.rule { height: 1px; background: rgba(255, 255, 255, 0.06); }
.body { padding: 14px 16px 4px; }
.body p { font-size: 13px; color: rgb(161, 161, 170); line-height: 1.55; }
.body p b { color: rgb(228, 228, 231); font-weight: 600; }
.row { display: flex; align-items: center; justify-content: space-between; gap: 12px; padding: 10px 16px; border-bottom: 1px solid rgba(255, 255, 255, 0.05); }
.row:last-of-type { border-bottom: 0px; }
.row .k { font-size: 12.5px; color: rgb(139, 139, 147); }
.row .v { font-size: 12.5px; font-weight: 600; font-variant-numeric: tabular-nums; }
select { font-family: inherit; font-size: 12.5px; font-weight: 600; color: rgb(250, 250, 250); background: rgba(255, 255, 255, 0.06); border: 1px solid rgba(255, 255, 255, 0.09); border-radius: 7px; padding: 5px 9px; cursor: pointer; }
select:focus-visible { outline: rgb(239, 68, 68) solid 2px; outline-offset: 1px; }
.primary { display: block; width: calc(100% - 32px); margin: 14px 16px; padding: 10px 14px; font-family: inherit; font-size: 13.5px; font-weight: 600; cursor: pointer; background: rgb(239, 68, 68); color: rgb(255, 255, 255); border: 0px; border-radius: 8px; }
.primary:hover { background: rgb(220, 38, 38); }
.primary.quiet { background: rgba(255, 255, 255, 0.06); color: rgb(250, 250, 250); }
.primary.quiet:hover { background: rgba(255, 255, 255, 0.1); }
.foot { padding: 0px 16px 14px; }
.foot .link { background: none; border: 0px; padding: 0px; cursor: pointer; font-family: inherit; font-size: 12px; color: rgb(139, 139, 147); text-decoration: underline rgba(239, 68, 68, 0.5); text-underline-offset: 3px; }
.foot .link:hover { color: rgb(250, 250, 250); }
[hidden] { display: none !important; }
